        errors.append(f"body is {len(body)} characters; maximum is {max_body_length}")

    return errors


def main() -> int:
    if len(sys.argv) != 2:
        print("Usage: commit-msg <commit-message-file>", file=sys.stderr)
        return 2

    try:
        message = Path(sys.argv[1]).read_text(encoding="utf-8")
